AI Symptom Checker Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("AI Symptom Checker Container", "AI Symptom Checker Container") {
    Component(Triage Controller, "Triage Controller", "Python, FastAPI, Server-Sent Events/SSE", "Handles incoming sanitized requests from the API Gateway and streams triage results over unstable rural internet connections.")
    Component(AI Inference Engine, "AI Inference Engine", "Confidential VMs with AMD SEV-SNP, GCP Binary Authorization", "Executes symptom checking models in memory securely, protecting patient health data and verifying model weights cryptographically.")
    Component(Audit Logger, "Audit Logger", "HTTPS TLS 1.3, GCP Cloud Storage WORM APIs", "Persists immutable audit logs and versioned inputs to regional WORM storage buckets for compliance.")
}

Rel(Triage Controller, AI Inference Engine, "Invokes inference on sanitized inputs", "In-Memory Confidential Computing")
Rel(AI Inference Engine, Audit Logger, "Persists immutable audit logs and versioned inputs", "HTTPS TLS 1.3")
@enduml

Local Pharmacy Integration Containers.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(local_pharmacy_integration_containers, "Local Pharmacy Integration Containers") {
    Component(Prescription Router, "Prescription Router", "Istio Service Mesh and Envoy", "Routes e-prescription requests to local pharmacy networks using mTLS.")
    Component(FHIR Adapter, "FHIR Adapter", "HL7 FHIR (US) and national EU standards", "Transforms payloads to meet local pharmacy network transmission standards.")
    Component(Event Publisher, "Event Publisher", "GCP Pub/Sub Client", "Publishes state-change events and manages retries via dead-letter queues.")
    Component(Audit Logger, "Audit Logger", "GCP Cloud Storage WORM Client", "Immutably logs transmission payloads and ACK/NACK responses.")
}

Rel(Prescription Router, FHIR Adapter, "Transforms e-prescription payloads")
Rel(FHIR Adapter, Event Publisher, "Publishes state-change events")
Rel(Event Publisher, Audit Logger, "Triggers immutable logging of transmission payloads")

@enduml

Regional WORM Storage Buckets.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
